const arr = [1, 2, 3, 4, 5];
const set = new Set([1, 2, 3, 4, 5]);
const map = new Map([['a', 1], ['b', 2], ['c', 3]]);

console.log(...arr); // 1 2 3 4 5
console.log(...set); // 1 2 3 4 5
console.log(...map); // [ 'a', 1 ] [ 'b', 2 ] [ 'c', 3 ]

const obj = {
  [Symbol.iterator]: function* () {
    yield 1;
    yield 2;
    yield 3;
  }
}

console.log(...obj); // 1 2 3
